<?php
// Inventory-only reset: no database creation/deletion, schema changes or SKU conversion.
function ir_admin(){if(current_user()['role']!=='Admin')throw new Exception('Administrator access required.');if(!item_codes_ready())throw new Exception('The existing Fresh Start schema must be installed first.');}
function ir_scope(){return item_code_scope();}
function ir_hash_rows($table,$rows){if($table==='settings')$rows=array_values(array_filter($rows,fn($r)=>$r['key_name']!=='backup_last_success'&&!str_starts_with($r['key_name'],'notification_read_')));return backup_rows_hash($rows);}
function ir_state(){global $CFG;$scope=ir_scope();$actual=db()->query("SHOW FULL TABLES WHERE Table_type='BASE TABLE'")->fetchAll(PDO::FETCH_COLUMN);$expected=array_merge($scope['clear'],$scope['keep']);$unknown=array_unique(array_merge(array_diff($actual,$expected),array_diff($expected,$actual)));if($unknown)throw new Exception('Reset blocked: unreviewed tables '.implode(', ',$unknown).'.');$state=[];foreach($actual as $table){$q=db()->prepare('SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=? AND TABLE_NAME=?');$q->execute([$CFG['db_name'],$table]);if($q->fetchColumn()!=='InnoDB')throw new Exception('Transactional InnoDB storage required: '.$table);if(in_array($table,['code_reset_runs','process_backups','activity_log','om_alerts'],true))continue;$state[$table]=ir_hash_rows($table,db()->query('SELECT * FROM '.backup_identifier($table))->fetchAll());}ksort($state);return $state;}
function ir_verify_integrity($id){ir_admin();$b=backup_record($id);$zip=new ZipArchive();if($zip->open($b['path'],ZipArchive::CHECKCONS)!==true)throw new Exception('Backup archive is unreadable or inconsistent.');try{$raw=$zip->getFromName('backup_manifest.json');if($raw===false)throw new Exception('Backup manifest missing.');$m=json_decode($raw,true,512,JSON_THROW_ON_ERROR);if(($m['reference']??'')!==$b['backup_ref']||empty($m['files'])||!isset($m['files']['database.json'],$m['files']['database.sql'],$m['files']['application/lib.php']))throw new Exception('Incomplete backup manifest.');if($zip->numFiles!==count($m['files'])+1)throw new Exception('Backup contains unexpected or duplicate entries.');foreach($m['files'] as $name=>$hash){if(!is_string($name)||str_contains($name,'..')||str_starts_with($name,'/')||str_contains($name,':')||!preg_match('/^[a-f0-9]{64}$/D',(string)$hash))throw new Exception('Invalid backup manifest entry.');$bytes=$zip->getFromName($name);if($bytes===false||!hash_equals($hash,hash('sha256',$bytes)))throw new Exception('Backup integrity failed: '.$name);}$snapshot=json_decode($zip->getFromName('database.json'),true,512,JSON_THROW_ON_ERROR);if(empty($snapshot['tables']))throw new Exception('Backup has no database snapshot.');$state=[];foreach($snapshot['tables'] as $table=>$data){backup_identifier($table);if(!isset($data['create'],$data['rows'],$data['hash'])||!is_array($data['rows'])||!str_starts_with($data['create'],'CREATE TABLE '.backup_identifier($table))||!hash_equals($data['hash'],backup_rows_hash($data['rows'])))throw new Exception('Invalid database snapshot: '.$table);if(!in_array($table,['code_reset_runs','process_backups','activity_log','om_alerts'],true))$state[$table]=ir_hash_rows($table,$data['rows']);}ksort($state);return ['archive_sha256'=>hash_file('sha256',$b['path']),'files'=>count($m['files']),'tables'=>count($snapshot['tables']),'state'=>$state,'verified_at'=>date(DATE_ATOM),'restore_tested'=>false];}finally{$zip->close();}}
function ir_run($id){$r=item_code_run($id);$r['plan']=json_decode($r['plan_json'],true,512,JSON_THROW_ON_ERROR);if(($r['plan']['mode']??'')!=='inventory-transactions-only-v1')throw new Exception('This is a legacy reset/renumbering record. Prepare a new Inventory / Transaction Reset.');return $r;}
function ir_prepare($reason){ir_admin();$reason=process_reason($reason);$before=ir_state();$id=backup_create();$verified=ir_verify_integrity($id);$after=ir_state();if($before!==$after||$verified['state']!==$after)throw new Exception('Inventory or master data changed while backing up. No reset was prepared. Pause transactions and prepare again.');$counts=[];foreach(ir_scope()['clear'] as $t)$counts[$t]=(int)db()->query('SELECT COUNT(*) FROM '.backup_identifier($t))->fetchColumn();$plan=['mode'=>'inventory-transactions-only-v1','scope'=>ir_scope(),'reason'=>$reason,'state'=>$after,'counts'=>$counts,'verification'=>$verified,'sku_changes'=>0];$ref=next_ref('INVRESET').'-'.bin2hex(random_bytes(3));$digest=hash('sha256',json_encode($plan));db()->prepare("INSERT INTO code_reset_runs(run_ref,status,backup_id,plan_json,review_digest,created_by) VALUES(?,'Prepared',?,?,?,?)")->execute([$ref,$id,json_encode($plan),$digest,current_user()['id']]);$run=(int)db()->lastInsertId();audit('Prepare Inventory / Transaction Reset','System',$ref,'Backup integrity verified; not restore-tested; no inventory cleared.');return $run;}
function ir_apply($id,$digest,$phrase,$password,$reviewAck,$downloadAck){ir_admin();if(!$reviewAck||!$downloadAck||$phrase!=='RESET INVENTORY')throw new Exception('Review the scope, save the backup copy and type RESET INVENTORY.');$rate='inventory-reset-'.current_user()['id'];login_rate_update($rate,'check');$q=db()->prepare("SELECT password_hash FROM users WHERE id=? AND active=1 AND role='Admin'");$q->execute([current_user()['id']]);$hash=$q->fetchColumn();if(!$hash||!password_verify($password,$hash)){login_rate_update($rate,'failure');throw new Exception('Current Admin password is incorrect.');}login_rate_update($rate,'success');return process_transaction(function()use($id,$digest){$q=db()->prepare('SELECT status FROM code_reset_runs WHERE id=? FOR UPDATE');$q->execute([$id]);$r=ir_run($id);if($r['status']!=='Prepared')throw new Exception('This reset is already applied or closed.');if(!hash_equals($r['review_digest'],(string)$digest))throw new Exception('Reset preview token changed.');$plan=$r['plan'];if($plan['scope']!==ir_scope()||$plan['state']!==ir_state())throw new Exception('Stocks, transactions or setup changed after preparation. Create a new verified backup and preview.');$check=ir_verify_integrity($r['backup_id']);if(!hash_equals($plan['verification']['archive_sha256'],$check['archive_sha256'])||$check['state']!==$plan['state'])throw new Exception('The verified backup changed. Reset blocked.');$keep=[];foreach(ir_scope()['keep'] as $t){if($t==='code_reset_runs')continue;$rows=db()->query('SELECT * FROM '.backup_identifier($t))->fetchAll();if($t==='settings')$rows=array_values(array_filter($rows,fn($v)=>$v['key_name']!=='beginning_locked'));$keep[$t]=backup_rows_hash($rows);}foreach(ir_scope()['clear'] as $t)db()->exec('DELETE FROM '.backup_identifier($t));set_setting('beginning_locked','0');foreach(ir_scope()['clear'] as $t)if((int)db()->query('SELECT COUNT(*) FROM '.backup_identifier($t))->fetchColumn())throw new Exception('Reset incomplete: '.$t);foreach($keep as $t=>$hash){$rows=db()->query('SELECT * FROM '.backup_identifier($t))->fetchAll();if($t==='settings')$rows=array_values(array_filter($rows,fn($v)=>$v['key_name']!=='beginning_locked'));if(!hash_equals($hash,backup_rows_hash($rows)))throw new Exception('Preserved data changed: '.$t);}$result=['inventory_reset'=>true,'stocks_zero'=>true,'transaction_history_cleared'=>true,'sku_changes'=>0,'master_data_preserved'=>true,'beginning_balance_unlocked'=>true,'backup_id'=>(int)$r['backup_id'],'backup_integrity_verified'=>true,'restore_tested'=>false];db()->prepare("UPDATE code_reset_runs SET status='Applied',result_json=?,applied_by=?,applied_at=NOW() WHERE id=?")->execute([json_encode($result),current_user()['id'],$id]);unset($GLOBALS['OM_RESERVED']);audit('Inventory / Transaction Reset','System',$r['run_ref'],json_encode($result).'; '.$plan['reason']);return $result;});}
function ir_cancel($id){ir_admin();$r=ir_run($id);$q=db()->prepare("UPDATE code_reset_runs SET status='Cancelled' WHERE id=? AND status='Prepared'");$q->execute([$id]);if(!$q->rowCount())throw new Exception('Only an unapplied prepared reset can be cancelled.');audit('Cancel Inventory Reset Preview','System',$r['run_ref'],'No inventory changed.');}
function ir_session_guard(){if(empty($_SESSION['uid'])||!item_codes_ready())return;$latest=(int)db()->query("SELECT COALESCE(MAX(id),0) FROM code_reset_runs WHERE status='Applied' AND run_ref LIKE 'INVRESET-%'")->fetchColumn();if((int)($_SESSION['inventory_reset_epoch']??0)!==$latest&&$latest>0)foreach(array_keys($_SESSION) as $key)if(preg_match('/^(workflow_edit_|warranty_reviews$|cancelled_order_cart_|receiving_|manual_receiv|repackaging_|count_upload_)/',$key))unset($_SESSION[$key]);$_SESSION['inventory_reset_epoch']=$latest;}
